const items = $input.all();
const results = [];

function normalizePhone(raw) {
  if (!raw) return null;
  let p = String(raw).replace(/[\s\-\.\(\)]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p.startsWith('+')) return /^\+\d{8,15}$/.test(p) ? p : null;
  if (/^05\d{8}$/.test(p)) return '+966' + p.slice(1);
  if (/^5\d{8}$/.test(p))  return '+9665' + p.slice(1);
  if (/^966\d{9}$/.test(p)) return '+' + p;
  if (/^(50|52|54|55|56)\d{7}$/.test(p)) return '+971' + p;
  if (/^01[0125]\d{8}$/.test(p)) return '+20' + p.slice(1);
  if (/^07\d{8}$/.test(p)) return '+967' + p.slice(1);
  if (/^08\d{8,11}$/.test(p)) return '+62' + p.slice(1);
  if (p.length >= 8) return '+' + p;
  return null;
}
function extractPhones(text) {
  if (!text) return [];
  const regex = /((?:\+|00)?\d{1,3}[\s\-\.]?[\d]{1,3}[\s\-\.]?[\d\s\-\.]{6,14})/g;
  return [...new Set((text.match(regex) || []).map(normalizePhone).filter(Boolean))];
