// Code – Filter Spam & Hash (مُحسَّن)
// الوظيفة:
//   1. استبعاد السبام والنصوص الفارغة
//   2. توليد content_hash فريد لمنع التكرار
//   3. تمرير جميع حقول البيانات الأصلية كاملة
// ════════════════════════════════════════════════════════════════════════

const items = $input.all();
const results = [];

const BLACKLIST_PATTERNS = [
  /follow\s*me/i, /check\s*my\s*bio/i, /buy\s+followers/i,
  /كسب\s+المال/, /ربح\s+من\s+المنزل/, /اشتراك\s+مجاني/,
  /t\.me\//i, /ارباح\s+يومية/, /استثمار\s+مضمون/,
  /فرصة\s+عمل/, /مندوب/, /اضغط\s+هنا/,
  /^[آأا]+[هه]+[!؟]*$/, /^\d+$/, /^[👍❤️🙏]+$/u
];

const seenHashes = new Set();
const now = new Date().toISOString();

for (const item of items) {
  const d = item.json;
  // تخطي عناصر skip
  if (d.skip === true) continue;

  const text = (d.raw_text || d.text || d.message || '').trim();

  // فلترة الحجم: 4 حروف كحد أدنى، 600 كحد أقصى
  if (!text || text.length < 4 || text.length > 600) continue;

  // استبعاد السبام
  if (BLACKLIST_PATTERNS.some(p => p.test(text))) continue;

  // توليد الهاش
  const hashBase = [d.platform || '', d.username || '', text.substring(0, 80)].join('|');
  let h = 0;
  for (let i = 0; i < hashBase.length; i++) h = Math.imul(31, h) + hashBase.charCodeAt(i) | 0;
  const contentHash = `CH-${Math.abs(h).toString(36).toUpperCase().padStart(8, '0')}`;

  if (seenHashes.has(contentHash)) continue;
  seenHashes.add(contentHash);

  // ✅ تمرير جميع الحقول الأصلية + إضافة content_hash
  results.push({
    json: {
      // ── جميع حقول المصدر (محفوظة كاملة) ────────────────
      raw_text:     text,
      username:     d.username     || '',
      full_name:    d.full_name    || d.username || '',
      profile_url:  d.profile_url  || '',
      post_url:     d.post_url     || '',
      post_text:    d.post_text    || '',
      comment_id:   d.comment_id   || '',
      posted_at:    d.posted_at    || '',
      likes_count:  d.likes_count  || 0,
      reply_count:  d.reply_count  || 0,
      phones_found: Array.isArray(d.phones_found) ? d.phones_found : [],
      has_phone:    d.has_phone    || false,
      platform:     d.platform     || 'Unknown',
      source:       d.source       || 'Radar',
      item_type:    d.item_type    || 'comment',
      is_demo:      d.is_demo      || false,
      // ── حقول مُضافة ────────────────────────────────────
      content_hash: contentHash,
      text_length:  text.length,
      captured_at:  d.captured_at  || now,
      status:       'Potential Lead'
    }
  });
}

console.log(`✅ Filter: ${results.length} leads passed out of ${items.length} inputs`);
return results.length > 0 ? results : [];

