// ── تحليل مخرجات AI ──────────────────────────────────────────────────
function parseAIOutput(raw) {
  if (!raw) return {};
  try {
    let clean = String(raw)
      .replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
    // قد تكون مصفوفة
    let parsed = JSON.parse(clean);
    if (Array.isArray(parsed)) parsed = parsed[0] || {};
    return parsed || {};
  } catch (e) {
    // محاولة استخراج أول JSON كائن
    const match = String(raw).match(/\{[\s\S]*?\}/);
    if (match) { try { return JSON.parse(match[0]); } catch { return {}; } }
    return {};
  }
}

// ── توحيد الأرقام ────────────────────────────────────────────────────
function normalizePhone(raw) {
  if (!raw || raw === 'null' || raw === 'false') return null;
  let p = String(raw).replace(/[\s\-\.\(\)]/g, '');
  // استبعاد آيديات فيسبوك الطويلة
  if (p.length > 15) return null;
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p.startsWith('+')) return /^\+\d{10,14}$/.test(p) ? p : null;
  if (/^05\d{8}$/.test(p)) return '+966' + p.slice(1);
  if (/^5\d{8}$/.test(p))  return '+966' + p;
  if (/^966\d{9}$/.test(p)) return '+' + p;
  if (/^01[0125]\d{8}$/.test(p)) return '+20' + p.slice(1);
  if (/^(50|52|54|55|56)\d{7}$/.test(p)) return '+971' + p;
  if (p.length >= 9 && p.length <= 12) return '+' + p;
  return null;
}

// ── استخراج البيانات الأصلية من Loop ─────────────────────────────────
function getOriginalData(aiItem, index, loopItems) {
  if (loopItems[index]?.json?.raw_text) return loopItems[index].json;
  if (aiItem._orig?.raw_text) return aiItem._orig;
  return {
    raw_text: '', full_name: '', username: '', profile_url: '', post_url: '',
    comment_id: '', platform: 'Unknown', source: 'Radar',
    phones_found: [], captured_at: new Date().toISOString(),
    _missing: true
  };
}

// ── المعالجة الرئيسية ────────────────────────────────────────────────
const results = [];
const now = new Date().toISOString();

for (let index = 0; index < aiItems.length; index++) {
  const aiItem = aiItems[index].json;
  const orig    = getOriginalData(aiItem, index, loopItems);

  // تحليل AI
  const aiRaw  = aiItem.text || aiItem.output || '';
  const ai     = parseAIOutput(aiRaw);

  // الحقول من AI (مع قيم افتراضية)
  const intent  = ai.intent   || 'info_seeking';
  const urgency = ai.urgency  || 'unknown';
  const quality = Math.max(0, Math.min(100, Number(ai.lead_quality) || 20));
  const reason  = ai.ai_reason || 'تحليل غير متاح';

  // الهواتف: من AI + من الأصل
  const aiPhone    = normalizePhone(ai.detected_phone);
  const origPhones = Array.isArray(orig.phones_found) ? orig.phones_found : [];
  const allPhones  = [...new Set([...origPhones, aiPhone].filter(Boolean))];
  const phone      = allPhones[0] || 'empty';

  // ✅ رفع الجودة تلقائياً إذا وجد هاتف
  const finalQuality = allPhones.length > 0 ? Math.max(quality, 80) : quality;

  // التصنيف
  let category = 'COLD';
  if (finalQuality >= 70) category = 'HOT';
  else if (finalQuality >= 40) category = 'WARM';

  // رحلة العميل
  const journeyMap = {
    booking_ready:       'hot_booking',
    booking_research:    'warm_research',
    travel_planning:     'planning',
    info_seeking:        'cold_info',
    complaint_competitor:'cold_competitor',
    irrelevant:          'filtered'
  };
  const journeyStep = journeyMap[intent] || 'awareness';

  // lead_id
  const ts    = Date.now().toString(36).toUpperCase();
  const rand  = Math.random().toString(36).slice(2, 5).toUpperCase();
  const leadId = orig.lead_id || `LD-${ts.slice(-5)}-${rand}`;

  // النص المنظف
  const cleanText = (orig.raw_text || '').replace(/https?:\/\/[^\s]+/g, '').trim();

  results.push({ json: {
    // ── هوية العميل ───────────────────────────────────────────────
    lead_id:       leadId,
    content_hash:  orig.content_hash || `CH-${ts.slice(-8)}`,
    name:          orig.full_name || orig.username || 'عميل غير معروف',
    full_name:     orig.full_name || '',
    username:      orig.username  || '',
    // ── الهاتف ─────────────────────────────────────────────────
    phone:         phone,
    phones_found:  allPhones,
    has_phone:     allPhones.length > 0,
    phone_count:   allPhones.length,
    // ── بيانات إضافية ────────────────────────────────────────
    email:         orig.email       || '',
    nationality:   orig.nationality || '',
    // ── المصدر ──────────────────────────────────────────────
    source:        orig.source   || 'Radar',
    platform:      orig.platform || 'Unknown',
    item_type:     orig.item_type || 'comment',
    // ── تحليل AI ─────────────────────────────────────────────
    radar_intent:  intent,
    radar_urgency: urgency,
    radar_quality: finalQuality,
    lead_quality:  finalQuality,
    score:         finalQuality,
    final_score:   finalQuality,
    ai_reason:     reason,
    notes:         reason,
    // ── التصنيف ──────────────────────────────────────────────
    category:      category,
    lead_category: category,
    journey_step:  journeyStep,
    // ── تفضيلات السفر ─────────────────────────────────────
    budget_signal:    ai.budget_signal    || 'unknown',
    travel_group:     ai.travel_group     || 'unknown',
    stars_preference: String(ai.stars_preference || 'unknown'),
    pax_hint:         Math.max(0, Number(ai.pax_count)  || 0),
    check_in_hint:    ai.check_in_hint    || '',
    nights_hint:      Math.max(0, Number(ai.nights_hint) || 0),
    // ── المحتوى ──────────────────────────────────────────────
    raw_text:      orig.raw_text  || '',
    last_message:  cleanText,
    message:       cleanText,
    // ── الروابط ───────────────────────────────────────────
    profile_url:   orig.profile_url  || '',
    post_url:      orig.post_url     || '',
    comment_id:    orig.comment_id   || '',
    likes_count:   Number(orig.likes_count)  || 0,
    reply_count:   Number(orig.reply_count)  || 0,
    // ── توقيت ────────────────────────────────────────────
    consent:       allPhones.length > 0,
    created_at:    orig.captured_at || now,
    captured_at:   orig.captured_at || now,
    updated_at:    now,
    archived_at:   '',
    assigned_to:   '',
    // ── أعلام النظام ─────────────────────────────────────
    is_demo:       orig.is_demo   || false,
    flow_origin:   'Bluevia Travel_F1_Radar',
    is_radar:      true,
    is_direct_inbound: false
  }});
}

console.log(`✅ Enriched: ${results.length} | HOT: ${results.filter(r=>r.json.category==='HOT').length} | WARM: ${results.filter(r=>r.json.category==='WARM').length}`);
return results;

